<?php $inactive = array_filter($items, function($item){return (int)$item['is_active'] !== 1;}); if ($inactive): ?><div class="panel_s"><div class="panel-body"><h4>Paused tasks</h4><?php foreach($inactive as $item): ?><div class="clearfix" style="margin-bottom:10px"><span><?php echo html_escape($item['title']); ?></span><form class="pull-right" method="post" action="<?php echo admin_url('smart_daily_productivity/checklist?date=' . urlencode($date)); ?>"><?php echo form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()); ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?php echo (int)$item['id']; ?>"><input type="hidden" name="active" value="1"><button class="btn btn-default btn-xs" type="submit">Restore</button></form></div><?php endforeach; ?></div></div><?php endif; ?></div></div></div></div>
<script>var sdpTaskData=<?php echo json_encode(array_map(function($x){return ['id'=>(int)$x['id'],'title'=>$x['title'],'notes'=>$x['notes']];}, $items), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;function sdpEditTask(id){var t=sdpTaskData.find(function(x){return x.id===id});if(!t)return;document.getElementById('sdp-task-action').value='edit';document.getElementById('sdp-task-id').value=id;document.getElementById('sdp-task-title').value=t.title;document.getElementById('sdp-task-notes').value=t.notes;document.getElementById('sdp-task-editor').scrollIntoView({behavior:'smooth'});}function sdpResetTask(){document.getElementById('sdp-task-editor').reset();document.getElementById('sdp-task-action').value='add';document.getElementById('sdp-task-id').value=0;}</script>
